;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#ATTAQUEDISSIPANTE&quot; title=&quot;Les talents de roublard&quot;&gt;Attaque dissipante&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#COLPORTEURDERUMEURS&quot; title=&quot;Les talents de roublard&quot;&gt;Colporteur de rumeurs&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#ESQUIVEEXTRAORDINAIRE&quot; title=&quot;Les talents de roublard&quot;&gt;Esquive extraordinaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#MAITREDELAFUITE&quot; title=&quot;Les talents de roublard&quot;&gt;Ma&#238;tre de la fuite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#SUBTILISATIONDARME&quot; title=&quot;Les talents de roublard&quot;&gt;Subtilisation d’arme&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Description des talents de roublard&lt;a class=&quot;headeranchor&quot; id=&quot;Description_des_talents_de_roublard_99&quot; href=&quot;#Description_des_talents_de_roublard_99&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
